namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F.\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and drizzle olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast\nYogurt\nGaram masala\nTurmeric\nCumin\nCanned tomatoes\nHeavy cream\nGarlic\nGinger\nOnion", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or pan-fry chicken until charred.\n3. Sauté onion, garlic, and ginger.\n4. Add tomatoes and simmer 15 minutes.\n5. Stir in cream and spices.\n6. Add chicken and simmer 10 minutes.", AverageRating = 4.8, RatingCount = 25 },
        new Recipe { Id = 3, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomato\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.", AverageRating = 4.2, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles\nShrimp or tofu\nEggs\nBean sprouts\nGreen onions\nPeanuts\nLime\nFish sauce\nTamarind paste\nSugar", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Make sauce: mix tamarind, fish sauce, and sugar.\n3. Stir-fry shrimp/tofu, push to side.\n4. Scramble eggs in the same pan.\n5. Add drained noodles and sauce, toss together.\n6. Top with peanuts, bean sprouts, and lime.", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale or pancetta\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted water until al dente.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, stir in egg mixture quickly.\n6. Serve immediately with extra pecorino.", AverageRating = 4.7, RatingCount = 20 },
        new Recipe { Id = 6, Title = "Sushi Rolls", Category = "Japanese", Ingredients = "Sushi rice\nNori sheets\nFresh salmon or tuna\nCucumber\nAvocado\nRice vinegar\nSoy sauce\nWasabi", Steps = "1. Cook sushi rice and season with rice vinegar.\n2. Place nori on bamboo mat, spread rice evenly.\n3. Arrange fish and vegetables in a line.\n4. Roll tightly using the mat.\n5. Slice with a wet knife.\n6. Serve with soy sauce and wasabi.", AverageRating = 4.4, RatingCount = 10 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve avocados and remove pits.\n2. Mash avocado to desired consistency.\n3. Dice onion, tomato, jalapeño, and cilantro.\n4. Mix all ingredients together.\n5. Add lime juice, garlic, and salt to taste.\n6. Serve immediately with tortilla chips.", AverageRating = 4.3, RatingCount = 18 },
        new Recipe { Id = 8, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock\nWhite miso paste\nTofu\nWakame seaweed\nGreen onions", Steps = "1. Heat dashi stock until simmering.\n2. Dissolve miso paste into the stock.\n3. Add cubed tofu and wakame.\n4. Simmer gently (do not boil).\n5. Serve topped with sliced green onions.", AverageRating = 4.1, RatingCount = 7 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var totalRatings = recipe.RatingCount + _ratings[recipeId].Count;
        var totalSum = recipe.AverageRating * recipe.RatingCount + _ratings[recipeId].Sum();
        recipe.AverageRating = Math.Round(totalSum / totalRatings, 1);
        recipe.RatingCount = totalRatings;
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}
"}

