@page "/"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>RecipeShare - Home</PageTitle>

<div class="container">
    <div class="text-center my-5">
        <h1>🍳 RecipeShare</h1>
        <p class="lead">Discover and share delicious recipes from around the world</p>
    </div>

    <h2 class="mb-4">Browse by Category</h2>
    <div class="row">
        @foreach (var category in RecipeService.GetCategories())
        {
            <div class="col-md-4 mb-4">
                <div class="card h-100">
                    <div class="card-body text-center">
                        <h3 class="card-title">@GetCategoryEmoji(category) @category</h3>
                        <p class="card-text text-muted">
                            @RecipeService.GetRecipesByCategory(category).Count recipe(s)
                        </p>
                        <a href="/category/@category" class="btn btn-primary">Browse Recipes</a>
                    </div>
                </div>
            </div>
        }
    </div>

    <div class="text-center mt-4">
        <a href="/submit" class="btn btn-success btn-lg">📝 Submit a Recipe</a>
    </div>
</div>

@code {
    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Mexican" => "🌮",
        "Thai" => "🍜",
        "Japanese" => "🍣",
        _ => "🍽️"
    };
}

@page "/category/{CategoryName}"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1>@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <p class="text-muted">No recipes found in this category.</p>
    }
    else
    {
        <div class="row">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6 mb-4">
                    <div class="card h-100">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="card-text">
                                <span class="text-warning">@GetStars(recipe.AverageRating)</span>
                                <small class="text-muted">(@recipe.AverageRating / 5 · @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public string CategoryName { get; set; } = string.Empty;

    private List<RecipeShare.Models.Recipe> Recipes { get; set; } = new();

    protected override void OnParametersSet()
    {
        Recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }

    private string GetStars(double rating)
    {
        int full = (int)Math.Floor(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"

@inject RecipeShare.Services.RecipeService RecipeService

<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            @if (Recipe is not null)
            {
                <li class="breadcrumb-item"><a href="/category/@Recipe.Category">@Recipe.Category</a></li>
                <li class="breadcrumb-item active">@Recipe.Title</li>
            }
        </ol>
    </nav>

    @if (Recipe is null)
    {
        <p class="text-danger">Recipe not found.</p>
    }
    else
    {
        <h1>@Recipe.Title</h1>
        <span class="badge bg-secondary mb-3">@Recipe.Category</span>

        <div class="my-3">
            <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />
        </div>

        <div class="row mt-4">
            <div class="col-md-4">
                <div class="card">
                    <div class="card-header"><strong>🥗 Ingredients</strong></div>
                    <ul class="list-group list-group-flush">
                        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <li class="list-group-item">@ingredient</li>
                        }
                    </ul>
                </div>
            </div>
            <div class="col-md-8">
                <div class="card">
                    <div class="card-header"><strong>📋 Steps</strong></div>
                    <div class="card-body">
                        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                        {
                            <p>@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeShare.Models.Recipe? Recipe { get; set; }

    protected override void OnParametersSet()
    {
        Recipe = RecipeService.GetRecipeById(Id);
    }
}

@rendermode InteractiveServer

@inject RecipeShare.Services.RecipeService RecipeService

<div class="d-inline-block">
    <span class="fs-4">
        @for (int i = 1; i <= 5; i++)
        {
            var star = i;
            <span role="button" class="@(star <= (HoverRating ?? DisplayRating) ? "text-warning" : "text-muted")"
                  style="cursor: pointer;"
                  @onclick="() => SubmitRating(star)"
                  @onmouseover="() => HoverRating = star"
                  @onmouseout="() => HoverRating = null">★</span>
        }
    </span>
    <small class="text-muted ms-2">@CurrentRating / 5 (@RatingCount ratings)</small>
    @if (Submitted)
    {
        <small class="text-success ms-2">✓ Thanks for rating!</small>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    [Parameter]
    public double CurrentRating { get; set; }

    [Parameter]
    public int RatingCount { get; set; }

    private int? HoverRating { get; set; }
    private int DisplayRating => (int)Math.Round(CurrentRating);
    private bool Submitted { get; set; }

    private void SubmitRating(int stars)
    {
        RecipeService.AddRating(RecipeId, stars);
        var recipe = RecipeService.GetRecipeById(RecipeId);
        if (recipe is not null)
        {
            CurrentRating = recipe.AverageRating;
            RatingCount = recipe.RatingCount;
        }
        Submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

@using RecipeShare.Models
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Success!</strong> Your recipe has been submitted.
            <a href="/recipe/@SubmittedId">View it here</a>.
        </div>
    }

    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => NewRecipe.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="NewRecipe.Ingredients"
                           placeholder="One ingredient per line" />
            <ValidationMessage For="() => NewRecipe.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps"
                           placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => NewRecipe.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
</div>

@code {
    private RecipeFormModel NewRecipe { get; set; } = new();
    private List<string> Categories { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = NewRecipe.Title,
            Category = NewRecipe.Category,
            Ingredients = NewRecipe.Ingredients,
            Steps = NewRecipe.Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedId = recipe.Id;
        SubmitSuccess = true;
        NewRecipe = new RecipeFormModel();
    }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeFormModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3)]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please list the ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please describe the steps.")]
    public string Steps { get; set; } = string.Empty;
}

