@page "/submit"
@rendermode InteractiveServer

@using RecipeShare.Models
@inject RecipeShare.Services.RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeShare</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1>📝 Submit a Recipe</h1>
    <p class="text-muted">Share your favorite recipe with the community!</p>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Success!</strong> Your recipe has been submitted.
            <a href="/recipe/@SubmittedId">View it here</a>.
        </div>
    }

    <EditForm Model="NewRecipe" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="NewRecipe.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => NewRecipe.Title" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="NewRecipe.Category">
                <option value="">-- Select a category --</option>
                @foreach (var cat in Categories)
                {
                    <option value="@cat">@cat</option>
                }
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => NewRecipe.Category" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="NewRecipe.Ingredients"
                           placeholder="One ingredient per line" />
            <ValidationMessage For="() => NewRecipe.Ingredients" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="NewRecipe.Steps"
                           placeholder="Describe each step on a new line" />
            <ValidationMessage For="() => NewRecipe.Steps" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
</div>

@code {
    private RecipeFormModel NewRecipe { get; set; } = new();
    private List<string> Categories { get; set; } = new();
    private bool SubmitSuccess { get; set; }
    private int SubmittedId { get; set; }

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private void HandleSubmit()
    {
        var recipe = new Recipe
        {
            Title = NewRecipe.Title,
            Category = NewRecipe.Category,
            Ingredients = NewRecipe.Ingredients,
            Steps = NewRecipe.Steps
        };

        RecipeService.AddRecipe(recipe);
        SubmittedId = recipe.Id;
        SubmitSuccess = true;
        NewRecipe = new RecipeFormModel();
    }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare.Models;

public class RecipeFormModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3)]
    public string Title { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please list the ingredients.")]
    public string Ingredients { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please describe the steps.")]
    public string Steps { get; set; } = string.Empty;
}

